#!/usr/bin/env python3
"""SYRD-428: the `team-launcher` argument parser, against the launcher it came out of.

`_build_parser` -- every verb, argument, choice, default and help line of the
legacy `team-launcher` entry point -- moved unchanged into
`scripts/launcher_parser.py`; the launcher re-exports it and `main` still builds
its parser through the launcher's name. This pins what makes that safe:

- **No cycle, one builder**, whichever module is imported first; the module
  alone loads nothing of Switchyard's; the `--script-path` default is still
  beside the launcher, because the launcher's own `__file__` is read when the
  parser is built.
- **Seams (rule 24):** the worktree policies, the pane-state default, the
  layout modes and the launcher's file are read through the launcher as often
  as before, so a patch there reaches the parser: the cases rebind each there
  and see the effect.
- **The behaviour is the baseline's:** every verb, representative options for
  each, the defaults, every choice list, invalid choices, unknown options,
  missing values and too many positionals (argparse's exit code and exact
  stderr), and `--help` byte for byte, through `main` as well. `GOLDEN` below
  was produced by running the BASELINE launcher's own parser over the very
  cases embedded here (`gold428.py`), not typed; the program name and help
  width are pinned, and the pane-state default -- which the environment decides
  at import -- is pinned on the launcher, so it is byte-identical under `env -i`,
  in a normal role pane and at another terminal width.

Nothing is dispatched. Spawns, every exec, signals, account and group lookups
and socket connections are refused for each case.
"""

from __future__ import annotations

import ast
import grp
import json
import os
import pwd
import socket
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

