def run_case(t: object, holder: object, spec: dict, reached: set) -> dict:
    """One parse against `holder`'s parser, with the program name and help width pinned and the launcher names wrapped."""
    import contextlib, io, os, sys
    from pathlib import Path as _P
    repo = str(_P(t.__file__).resolve().parent.parent)

    def norm(value):
        if isinstance(value, (list, tuple)):
            return [norm(v) for v in value]
        if isinstance(value, dict):
            return {str(k): norm(v) for k, v in sorted(value.items(), key=lambda kv: str(kv[0]))}
        if isinstance(value, _P):
            return "PATH " + norm(str(value))
        if isinstance(value, str):
            return value.replace(repo, "REPO")
        if isinstance(value, (int, float, bool)) or value is None:
            return value
        return repr(value)

    names = ["WORKTREE_POLICIES", "LAYOUT_MODE_CHOICES", "LAYOUT_MODE_AUTO", "DEFAULT_PANE_STATE_DIR", "__file__", "_build_parser"]
    saved = {n: getattr(t, n) for n in names}
    saved_argv0, saved_columns = sys.argv[0], os.environ.get("COLUMNS")
    out, err = io.StringIO(), io.StringIO()
    try:
        under = {n: getattr(holder, n) for n in FUNCTIONS}

        def build(*args, **kwargs):
            reached.add("_build_parser")
            return saved["_build_parser"](*args, **kwargs)
        t._build_parser = build
        # The real pane-state default is computed at import from the environment and the uid, so it would make the
        # help differ between a role pane and `env -i`; every case pins it on the launcher, where the parser reads it.
        for n, v in {"DEFAULT_PANE_STATE_DIR": "/nonexistent/syrd428/pane-state", **spec.get("launcher", {})}.items():
            setattr(t, n, v)
        sys.argv[0] = "team-launcher"
        os.environ["COLUMNS"] = "100"
        try:
            with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
                if spec["call"] == "parse":
                    got = norm(dict(sorted(vars(under["_build_parser"]().parse_args(spec["argv"])).items())))
                else:
                    got = norm(t.main(spec["argv"]))
        except SystemExit as exc:
            got = {"exit": exc.code if isinstance(exc.code, int) else norm(str(exc.code))}
        return {"result": got, "stdout": norm(out.getvalue()), "stderr": norm(err.getvalue())}
    finally:
        sys.argv[0] = saved_argv0
        if saved_columns is None:
            os.environ.pop("COLUMNS", None)
        else:
            os.environ["COLUMNS"] = saved_columns
        for n, v in saved.items():
            setattr(t, n, v)
