def test_every_answer_is_the_baselines() -> None:
    check(sorted(CASES) == sorted(GOLDEN), "every measured case is asserted, and nothing else")
    for label, spec in CASES.items():
        for holder in (m, t):
            got = run(holder, spec)
            check(got == GOLDEN[label], f"{label} ({holder.__name__}): the baseline's answer, every call in order: {got}")


def test_the_rules_hold_in_the_measured_record() -> None:
    def result(label):
        return GOLDEN[label]["result"]

    bare = result("parse: a project alone: start by default")
    check(bare["command"] == "start" and bare["layout"] == "auto" and bare["add_role_cli"] == "codex"
          and bare["script_path"] == "PATH REPO/scripts/team-launcher" and bare["pane_state_dir"] is None,
          f"a project alone: start, the automatic layout, codex for a new role, the script beside the launcher: {bare}")
    check(result("the launcher's file rebound")["script_path"] == "PATH /nonexistent/syrd428/scripts/team-launcher",
          "the script path follows the launcher's own file, read when the parser is built")
    import re
    unwrap = lambda text: re.sub(r"\n +", "", text)  # argparse wraps long help lines; rejoin them before looking inside
    help_text = GOLDEN["parse: help"]["stdout"]
    check(help_text.startswith("usage: team-launcher [-h]") and all(verb in help_text for verb in (
        "start", "attach", "reload", "stop", "design", "new", "provision-runtime", "deploy-launcher", "upgrade", "add-role",
        "set-vcs-close-role", "pane", "teardown")) and "(default: /nonexistent/syrd428/pane-state)" in unwrap(help_text),
          "help names every verb, and the pane-state default the launcher holds")
    check(GOLDEN["main's own help"]["stdout"] == help_text and result("main's own help") == {"exit": 0}, "main's own --help is the parser's")
    check(GOLDEN["parse: a layout nobody offers"]["stderr"].endswith(
              "team-launcher: error: argument --layout: invalid choice: 'tiled' (choose from 'auto', 'separate', 'viewer')\n")
          and result("parse: a layout nobody offers") == {"exit": 2}, "an unknown layout is refused by argparse, exit 2")
    check("(choose from 'shared', 'syrd428')" in GOLDEN["the policies rebound on the launcher"]["stderr"]
          and "syrd428" in GOLDEN["the layout modes rebound on the launcher"]["stdout"]
          and "(default: /nonexistent/syrd428/panes)" in unwrap(GOLDEN["the pane state directory rebound on the launcher"]["stdout"]),
          "the policies, layout modes and pane-state default are read through the launcher when the parser is built")
    design = result("parse: design, every option")
    check(design["audit_signoff"] is True and design["needs_inspection"] is False and design["linger"] is False
          and design["supplementary_groups"] == ["kvm", "video"] and design["worktree_policy"] == "isolated",
          "the design options: paired booleans, a repeated group, a declared policy")


def test_every_launcher_seam_is_reached() -> None:
    # Everything the parser reads through the launcher is a value, not a function: each is rebound there by a case
    # (the pane-state default in every case), and the parser builder itself is reached through main.
    names = {name for reads in SEAMS.values() for name in reads}
    rebound = {name for spec in CASES.values() for name in spec.get("launcher", {})} | {"DEFAULT_PANE_STATE_DIR"}
    check(names == rebound, f"every name the parser reads is rebound on the launcher by a case: {sorted(names)} {sorted(rebound)}")
    check("_build_parser" in REACHED, "and main builds it through the launcher's name")


STRUCTURE = ("test_the_module_loads_no_other_switchyard_module_at_import", "test_either_import_order_gives_one_parser_builder_and_the_launchers_script_path",
             "test_the_seams_read_through_the_launcher_and_nothing_bound", "test_the_launcher_reexports_it_and_main_reaches_it_there")
LAST = ("test_every_launcher_seam_is_reached",)


def main() -> int:
    names = sorted(name for name, value in globals().items() if name.startswith("test_") and callable(value))
    for name in [*STRUCTURE, *(name for name in names if name not in STRUCTURE + LAST), *LAST]:
        globals()[name]()
    print(f"launcher_parser_boundary_test: {CHECKS} checks ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
